-- Mae Yai On POS: central SQLite database foundation
-- IDs are generated by the application (UUID strings).
-- Monetary values are stored as integer satang; never use REAL for money.
-- Timestamps are ISO-8601 UTC strings generated by the application.
-- Enable foreign keys on EVERY database connection.

PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS schema_migrations (
    version       INTEGER PRIMARY KEY,
    name          TEXT NOT NULL,
    applied_at    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS app_settings (
    setting_key   TEXT PRIMARY KEY,
    setting_value TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS product_categories (
    id            TEXT PRIMARY KEY,
    name          TEXT NOT NULL COLLATE NOCASE UNIQUE,
    description   TEXT,
    is_active     INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS products (
    id                TEXT PRIMARY KEY,
    category_id       TEXT REFERENCES product_categories(id) ON DELETE RESTRICT,
    sku               TEXT COLLATE NOCASE UNIQUE,
    barcode           TEXT COLLATE NOCASE UNIQUE,
    name              TEXT NOT NULL,
    description       TEXT,
    unit_name         TEXT NOT NULL DEFAULT 'ชิ้น',
    sale_price_satang INTEGER NOT NULL DEFAULT 0 CHECK (sale_price_satang >= 0),
    cost_price_satang INTEGER NOT NULL DEFAULT 0 CHECK (cost_price_satang >= 0),
    stock_quantity    INTEGER NOT NULL DEFAULT 0 CHECK (stock_quantity >= 0),
    track_stock       INTEGER NOT NULL DEFAULT 1 CHECK (track_stock IN (0, 1)),
    is_active         INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS customers (
    id            TEXT PRIMARY KEY,
    customer_code TEXT COLLATE NOCASE UNIQUE,
    name          TEXT NOT NULL,
    phone         TEXT,
    email         TEXT,
    address       TEXT,
    note          TEXT,
    is_active     INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS sales (
    id                  TEXT PRIMARY KEY,
    receipt_number      TEXT NOT NULL COLLATE NOCASE UNIQUE,
    customer_id         TEXT REFERENCES customers(id) ON DELETE RESTRICT,
    status              TEXT NOT NULL DEFAULT 'draft'
                        CHECK (status IN ('draft', 'confirmed', 'voided')),
    subtotal_satang     INTEGER NOT NULL DEFAULT 0 CHECK (subtotal_satang >= 0),
    discount_satang     INTEGER NOT NULL DEFAULT 0 CHECK (discount_satang >= 0),
    tax_satang          INTEGER NOT NULL DEFAULT 0 CHECK (tax_satang >= 0),
    total_satang        INTEGER NOT NULL DEFAULT 0 CHECK (total_satang >= 0),
    paid_satang         INTEGER NOT NULL DEFAULT 0 CHECK (paid_satang >= 0),
    change_satang       INTEGER NOT NULL DEFAULT 0 CHECK (change_satang >= 0),
    note                TEXT,
    created_at          TEXT NOT NULL,
    confirmed_at        TEXT,
    voided_at           TEXT,
    updated_at          TEXT NOT NULL,
    CHECK (discount_satang <= subtotal_satang),
    CHECK (paid_satang >= change_satang)
);

CREATE TABLE IF NOT EXISTS sale_items (
    id                    TEXT PRIMARY KEY,
    sale_id               TEXT NOT NULL REFERENCES sales(id) ON DELETE RESTRICT,
    product_id            TEXT REFERENCES products(id) ON DELETE RESTRICT,
    product_name_snapshot TEXT NOT NULL,
    sku_snapshot          TEXT,
    quantity              INTEGER NOT NULL CHECK (quantity > 0),
    unit_price_satang     INTEGER NOT NULL CHECK (unit_price_satang >= 0),
    discount_satang       INTEGER NOT NULL DEFAULT 0 CHECK (discount_satang >= 0),
    line_total_satang     INTEGER NOT NULL CHECK (line_total_satang >= 0),
    created_at            TEXT NOT NULL,
    CHECK (discount_satang <= quantity * unit_price_satang)
);

CREATE TABLE IF NOT EXISTS payments (
    id                TEXT PRIMARY KEY,
    sale_id           TEXT NOT NULL REFERENCES sales(id) ON DELETE RESTRICT,
    payment_method    TEXT NOT NULL
                      CHECK (payment_method IN ('cash', 'transfer', 'card', 'other')),
    amount_satang     INTEGER NOT NULL CHECK (amount_satang > 0),
    reference_number  TEXT,
    note              TEXT,
    received_at       TEXT NOT NULL,
    created_at        TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS inventory_movements (
    id                TEXT PRIMARY KEY,
    product_id        TEXT NOT NULL REFERENCES products(id) ON DELETE RESTRICT,
    movement_type     TEXT NOT NULL
                      CHECK (movement_type IN ('opening', 'purchase', 'sale', 'sale_void', 'adjustment', 'return')),
    quantity_delta    INTEGER NOT NULL CHECK (quantity_delta <> 0),
    reference_type    TEXT,
    reference_id      TEXT,
    note              TEXT,
    created_at        TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS audit_logs (
    id             TEXT PRIMARY KEY,
    entity_type    TEXT NOT NULL,
    entity_id      TEXT NOT NULL,
    action         TEXT NOT NULL,
    before_json    TEXT,
    after_json     TEXT,
    actor_id       TEXT,
    occurred_at    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_products_category_active
    ON products(category_id, is_active);
CREATE INDEX IF NOT EXISTS idx_products_name
    ON products(name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS idx_customers_name
    ON customers(name COLLATE NOCASE);
CREATE INDEX IF NOT EXISTS idx_customers_phone
    ON customers(phone);
CREATE INDEX IF NOT EXISTS idx_sales_created_at
    ON sales(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sales_customer
    ON sales(customer_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sales_status
    ON sales(status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sale_items_sale
    ON sale_items(sale_id);
CREATE INDEX IF NOT EXISTS idx_sale_items_product
    ON sale_items(product_id);
CREATE INDEX IF NOT EXISTS idx_payments_sale
    ON payments(sale_id, received_at);
CREATE INDEX IF NOT EXISTS idx_inventory_product_time
    ON inventory_movements(product_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_inventory_reference
    ON inventory_movements(reference_type, reference_id);
CREATE INDEX IF NOT EXISTS idx_audit_entity
    ON audit_logs(entity_type, entity_id, occurred_at DESC);

-- Application write rules:
-- 1. Save a sale, its lines, payment rows, stock movements, and audit event
--    inside ONE database transaction.
-- 2. Only confirmed sales affect stock and reports.
-- 3. Do not physically delete confirmed sales, payments, or ledger entries.
--    Use a void workflow that writes compensating stock movements and audit data.
-- 4. Recalculate totals from sale_items on the application side before confirming;
--    never trust totals supplied by a UI screen.
-- 5. Keep foreign_keys enabled for every opened connection.
